CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL, c1 REAL CHECK(c1 IS NULL OR length(c1) < 40), c2 ANY, c3 TEXT CHECK(c3 IS NULL OR length(c3) < 40), c4 INTEGER) STRICT;
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(-22.615, 5.521, x'', 'delta', 21);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(25.329, -19.703, 615.3, 'beta', -92);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(-33.361, -11.179, 918, 'tau', -85);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(26.879, 1.744, NULL, 'beta', 48);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL, c1 NUMERIC CHECK(c1 IS NULL OR length(c1) < 40), c2 BLOB, c3 REAL, c4 TEXT CHECK(c4 IS NULL OR length(c4) < 40), ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(NULL, -4, 1, x'a625', x'c7e9', 1);
SELECT id, coalesce(iif(-(id), c1 IS NULL, x'350973'), c3 IN (id BETWEEN ref AND c3, 9223372036854775807, NULL)), CAST(c0 AS REAL) FROM t1 ORDER BY id, c0, c1, c2, c3, c4, ref;
SELECT CASE WHEN -(873 IS NULL) THEN iif((x'02ab7a2327' || 'MU'), -3, -1) ELSE NULL END, NULL;
SELECT id, iif(NOT ref, iif('phi', x'b6', x'86b5b280'), -4) BETWEEN '42' AND ref, nullif(coalesce(id, id), typeof(-558.6093)) BETWEEN ref IS NULL AND typeof(c2) FROM t1 ORDER BY id DESC, c0, c1, c2, c3, c4, ref;
SELECT nullif(-(x'1fe3fa6f') BETWEEN x'' AND 0, -(iif('tau', 'iota', 746.028))), NOT CAST(1e308 AS REAL);
SELECT id, coalesce(x'70f9cbeb82a8', 3) IN (c2 IS NULL, NULL, NULL) IN (x'919d0e0271', -2, 'epsilon'), CASE WHEN id THEN -773.039 ELSE c2 END FROM t1 ORDER BY id DESC, c0, c1, c2 DESC, c3 DESC, c4 DESC, ref;
SELECT NULL IN (NOT iif(x'af541b06dfbf', 894.4056, 'gamma'), -791.0396, -923.8497), x'';
SELECT id, c1, coalesce(CASE WHEN x'eae63f' THEN 'epsilon' ELSE x'a0d5fd' END BETWEEN (id | ref) AND CASE WHEN NULL THEN ref ELSE c4 END, -2) FROM t1 ORDER BY id, c0, c1 DESC, c2, c3 DESC, c4 DESC, ref;
SELECT x'c6ab76', CAST(x'92' AS NUMERIC) IN (x'', x'af3815', NULL) IS NULL;
SELECT id, iif(iif(c4 IN (2, -869.8, x'28c65872'), abs(c2), 'chi'), nullif(coalesce(c4, c3), CAST(x'5eb0' AS NUMERIC)), NULL), coalesce(946, id IN (NULL BETWEEN c3 AND -93.1, 488.3, 'alpha')) FROM t0 ORDER BY id, c0, c1, c2, c3 DESC, c4 DESC;
SELECT NOT abs('epsilon' IN (x'48adbc81', 'upsilon', x'd674c53a7d')), abs(nullif(2, 'beta') BETWEEN 208 AND x'ed385364');
SELECT id, nullif(c1, NULL), ref FROM t1 ORDER BY id, c0 DESC, c1, c2, c3, c4 DESC, ref;
SELECT NULL, typeof(NOT -263);
SELECT id, ref, id BETWEEN abs(id) AND abs(id) BETWEEN nullif(coalesce(NULL, id), (c0 >= c2)) AND ref FROM t1 ORDER BY id, c0, c1, c2, c3, c4 DESC, ref;
SELECT 700.26, typeof(iif(-674 BETWEEN x'cdd696ea' AND -629, NOT -4, NULL));
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t1.id) FROM t1 ORDER BY c0, id;
SELECT id FROM t1 WHERE id NOT IN (SELECT id FROM t1 WHERE coalesce(typeof(NULL), (NULL / 1))) ORDER BY id;
SELECT id FROM t1 x WHERE NOT EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 3) ORDER BY id;
SELECT ref FROM t1 EXCEPT SELECT c3 FROM t1 ORDER BY 1 LIMIT 3 OFFSET 3;
